import type {
  ItemsApiGetItemsRequest,
  MediaInfoApiGetPlaybackInfoRequest,
} from "@jellyfin/sdk/lib/generated-client";
import type { SolidQueryOptions } from "@tanstack/solid-query";
import { Effect, pipe } from "effect";
import type { Accessor } from "solid-js";
import {
  createEffectMutation,
  createEffectQuery,
  createQueryDataHelpers,
  createQueryKey,
  type ExtractQueryData,
} from "~/effect/tanstack/query";
import { safeAssign } from "~/lib/utils";
import { JellyfinCatalogueService } from "./service";
import type { Library, MediaItem, PlaybackMetadata } from "./types";

const LIBRARIES_TIMEOUT = "10 seconds";

type ItemQueryOptions = Accessor<
  Omit<
    SolidQueryOptions<
      MediaItem,
      unknown,
      MediaItem,
      ReturnType<typeof JellyfinCatalogueOperations.itemQueryKey>
    >,
    "queryFn" | "queryKey"
  >
>;

type PlaybackMetadataQueryOptions = Accessor<
  Omit<
    SolidQueryOptions<
      PlaybackMetadata,
      unknown,
      PlaybackMetadata,
      ReturnType<typeof JellyfinCatalogueOperations.playbackMetadataQueryKey>
    >,
    "queryFn" | "queryKey"
  >
>;

class JellyfinCatalogue {
  librariesQueryKey = createQueryKey("catalogueLibraries");
  librariesQueryDataHelpers = createQueryDataHelpers<Library[]>(
    this.librariesQueryKey
  );
  getLibraries = () =>
    createEffectQuery(() => ({
      queryKey: this.librariesQueryKey(),
      queryFn: () =>
        JellyfinCatalogueService.pipe(
          Effect.flatMap((catalogue) => catalogue.libraries()),
          Effect.timeout(LIBRARIES_TIMEOUT)
        ),
    }));

  resumeRailQueryKey = createQueryKey("catalogueResumeRail");
  resumeRailQueryDataHelpers = createQueryDataHelpers<MediaItem[]>(
    this.resumeRailQueryKey
  );
  getResumeRail = () =>
    createEffectQuery(() => ({
      queryKey: this.resumeRailQueryKey(),
      queryFn: () =>
        JellyfinCatalogueService.pipe(
          Effect.flatMap((catalogue) => catalogue.resumeRail())
        ),
    }));

  nextUpRailQueryKey = createQueryKey("catalogueNextUpRail");
  nextUpRailQueryDataHelpers = createQueryDataHelpers<MediaItem[]>(
    this.nextUpRailQueryKey
  );
  getNextUpRail = () =>
    createEffectQuery(() => ({
      queryKey: this.nextUpRailQueryKey(),
      queryFn: () =>
        JellyfinCatalogueService.pipe(
          Effect.flatMap((catalogue) => catalogue.nextUpRail({ limit: 4 }))
        ),
    }));

  latestMoviesQueryKey = createQueryKey<
    "catalogueLatestMovies",
    { search: string }
  >("catalogueLatestMovies");
  latestMoviesQueryDataHelpers = createQueryDataHelpers<
    MediaItem[],
    { search: string }
  >(this.latestMoviesQueryKey);
  getLatestMovies = (searchTerm: () => string, libraries?: Library[]) =>
    createEffectQuery(() => {
      const search = searchTerm();
      const movieLibraryId = libraries?.find(
        (library) => library.collectionType === "movies"
      )?.id;

      return {
        queryKey: this.latestMoviesQueryKey({ search }),
        queryFn: () =>
          JellyfinCatalogueService.pipe(
            Effect.flatMap((catalogue) =>
              search
                ? catalogue.items({
                    parentId: movieLibraryId,
                    enableImages: true,
                    fields: ["ParentId"],
                    includeItemTypes: ["Movie"],
                    limit: 7,
                    recursive: true,
                    searchTerm: search,
                  })
                : catalogue.latestMovieRail({ limit: 7 })
            )
          ),
        enabled: libraries?.some(
          (library) => library.collectionType === "movies"
        ),
      };
    });

  latestTVShowsQueryKey = createQueryKey<
    "catalogueLatestTVShows",
    { search: string }
  >("catalogueLatestTVShows");
  latestTVShowsQueryDataHelpers = createQueryDataHelpers<
    MediaItem[],
    { search: string }
  >(this.latestTVShowsQueryKey);
  getLatestTVShows = (searchTerm: () => string, libraries?: Library[]) =>
    createEffectQuery(() => {
      const search = searchTerm();
      const tvLibraryId = libraries?.find(
        (library) => library.collectionType === "tvshows"
      )?.id;

      return {
        queryKey: this.latestTVShowsQueryKey({ search }),
        queryFn: () =>
          JellyfinCatalogueService.pipe(
            Effect.flatMap((catalogue) =>
              search
                ? catalogue.items({
                    parentId: tvLibraryId,
                    enableImages: true,
                    fields: ["ParentId"],
                    includeItemTypes: ["Series"],
                    limit: 7,
                    recursive: true,
                    searchTerm: search,
                  })
                : catalogue.latestTvRail({ limit: 7 })
            )
          ),
        enabled: libraries?.some(
          (library) => library.collectionType === "tvshows"
        ),
      };
    });

  itemQueryKey = createQueryKey<"catalogueItem", { id: string }>(
    "catalogueItem"
  );
  itemQueryDataHelpers = createQueryDataHelpers<
    ExtractQueryData<ReturnType<typeof this.getItem>>,
    { id: string }
  >(this.itemQueryKey);
  getItem = (
    id: () => string,
    params?: ItemsApiGetItemsRequest,
    queryOptions?: ItemQueryOptions
  ) =>
    createEffectQuery(() => ({
      queryKey: this.itemQueryKey({ id: id() }),
      queryFn: () =>
        JellyfinCatalogueService.pipe(
          Effect.flatMap((catalogue) =>
            catalogue.itemById(id(), { enableImages: true, ...params })
          )
        ),
      ...(queryOptions ? queryOptions() : {}),
    }));

  itemsQueryKey = createQueryKey<
    "catalogueItems",
    { parentId?: string; ids?: string[]; searchTerm?: string }
  >("catalogueItems");
  itemsQueryDataHelpers = createQueryDataHelpers<
    MediaItem[],
    { parentId?: string; ids?: string[]; searchTerm?: string }
  >(this.itemsQueryKey);
  getItems = (
    params?:
      | ItemsApiGetItemsRequest
      | Accessor<ItemsApiGetItemsRequest | undefined>
  ) =>
    createEffectQuery(() => {
      const request = typeof params === "function" ? params() : params;

      return {
        queryKey: this.itemsQueryKey({
          parentId: request?.parentId,
          ids: request?.ids,
          searchTerm: request?.searchTerm,
        }),
        queryFn: () =>
          JellyfinCatalogueService.pipe(
            Effect.flatMap((catalogue) =>
              catalogue.items({ enableImages: true, ...request })
            )
          ),
      };
    });

  getNextEpisode = (item: () => MediaItem | undefined) =>
    createEffectQuery(() => ({
      queryKey: ["catalogueNextEpisode", { id: item()?.id }] as const,
      queryFn: () =>
        pipe(
          Effect.fromNullable(item()),
          Effect.flatMap((mediaItem) =>
            JellyfinCatalogueService.pipe(
              Effect.flatMap((catalogue) => catalogue.nextEpisode(mediaItem))
            )
          )
        ),
      enabled: () => Boolean(item()?.id),
    }));

  playbackMetadataQueryKey = createQueryKey<
    "cataloguePlaybackMetadata",
    { id: string }
  >("cataloguePlaybackMetadata");
  playbackMetadataDataHelpers = createQueryDataHelpers<
    PlaybackMetadata,
    { id: string }
  >(this.playbackMetadataQueryKey);
  getPlaybackMetadata = (
    id: () => string,
    params?: MediaInfoApiGetPlaybackInfoRequest,
    queryOptions?: PlaybackMetadataQueryOptions
  ) =>
    createEffectQuery(() => ({
      queryKey: this.playbackMetadataQueryKey({ id: id() }),
      queryFn: () =>
        JellyfinCatalogueService.pipe(
          Effect.flatMap((catalogue) => catalogue.playbackMetadata(id(), params))
        ),
      ...(queryOptions ? queryOptions() : {}),
    }));

  markItemPlayed = (id: string, onDone?: () => Promise<void> | void) =>
    createEffectMutation(() => ({
      mutationKey: ["catalogueMarkItemPlayed"],
      mutationFn: () =>
        Effect.gen(
          function* (this: JellyfinCatalogue) {
            this.itemQueryDataHelpers.cancelQuery({ id });
            const service = yield* JellyfinCatalogueService;
            const prevData = this.itemQueryDataHelpers.getData({ id });

            this.itemQueryDataHelpers.setData({ id }, (data) => {
              safeAssign(data, "userData", { played: true });
            });

            yield* service.markItemPlayed(id).pipe(
              Effect.catchTag("MutationError", (error) => {
                if (prevData) {
                  this.itemQueryDataHelpers.setData({ id }, prevData);
                }
                return Effect.fail(error);
              })
            );

            yield* Effect.promise(async () => {
              await this.itemQueryDataHelpers.invalidateQuery({ id });
              await onDone?.();
            });
          }.bind(this)
        ),
    }));

  markItemUnPlayed = (id: string, onDone?: () => Promise<void> | void) =>
    createEffectMutation(() => ({
      mutationKey: ["catalogueMarkItemUnPlayed"],
      mutationFn: () =>
        Effect.gen(
          function* (this: JellyfinCatalogue) {
            this.itemQueryDataHelpers.cancelQuery({ id });
            const service = yield* JellyfinCatalogueService;
            const prevData = this.itemQueryDataHelpers.getData({ id });

            this.itemQueryDataHelpers.setData({ id }, (data) => {
              safeAssign(data, "userData", {
                played: false,
                playbackPositionTicks: 0,
              });
            });

            yield* service.markItemUnPlayed(id).pipe(
              Effect.catchTag("MutationError", (error) => {
                if (prevData) {
                  this.itemQueryDataHelpers.setData({ id }, prevData);
                }
                return Effect.fail(error);
              })
            );

            yield* Effect.promise(async () => {
              await this.itemQueryDataHelpers.invalidateQuery({ id });
              await onDone?.();
            });
          }.bind(this)
        ),
    }));

  markItemFavorite = (id: string, onDone?: () => Promise<void> | void) =>
    createEffectMutation(() => ({
      mutationKey: ["catalogueMarkItemFavorite"],
      mutationFn: () =>
        Effect.gen(
          function* (this: JellyfinCatalogue) {
            this.itemQueryDataHelpers.cancelQuery({ id });
            const service = yield* JellyfinCatalogueService;
            const prevData = this.itemQueryDataHelpers.getData({ id });

            this.itemQueryDataHelpers.setData({ id }, (data) => {
              safeAssign(data, "userData", { favorite: true });
            });

            yield* service.markItemFavorite(id).pipe(
              Effect.catchTag("MutationError", (error) => {
                if (prevData) {
                  this.itemQueryDataHelpers.setData({ id }, prevData);
                }
                return Effect.fail(error);
              })
            );

            yield* Effect.promise(async () => {
              await this.itemQueryDataHelpers.invalidateQuery({ id });
              await onDone?.();
            });
          }.bind(this)
        ),
    }));

  markItemUnFavorite = (id: string, onDone?: () => Promise<void> | void) =>
    createEffectMutation(() => ({
      mutationKey: ["catalogueMarkItemUnFavorite"],
      mutationFn: () =>
        Effect.gen(
          function* (this: JellyfinCatalogue) {
            this.itemQueryDataHelpers.cancelQuery({ id });
            const service = yield* JellyfinCatalogueService;
            const prevData = this.itemQueryDataHelpers.getData({ id });

            this.itemQueryDataHelpers.setData({ id }, (data) => {
              safeAssign(data, "userData", { favorite: false });
            });

            yield* service.markItemUnFavorite(id).pipe(
              Effect.catchTag("MutationError", (error) => {
                if (prevData) {
                  this.itemQueryDataHelpers.setData({ id }, prevData);
                }
                return Effect.fail(error);
              })
            );

            yield* Effect.promise(async () => {
              await this.itemQueryDataHelpers.invalidateQuery({ id });
              await onDone?.();
            });
          }.bind(this)
        ),
    }));
}

export type JellyfinCatalogueOperationsType = JellyfinCatalogue;

export const JellyfinCatalogueOperations = new JellyfinCatalogue();

import type { RouteSectionProps } from "@solidjs/router";
import { createSignal, For, Show, splitProps } from "solid-js";
import { SeriesCard } from "~/components/media-card";
import { Nav } from "~/components/Nav";
import { QueryBoundary } from "~/components/query-boundary";
import { InlineLoading } from "~/components/ui/loading";
import { JellyfinOperations } from "~/effect/services/jellyfin/operations";
import LibraryIcon from "~icons/lucide/library";

// ── Skeleton grid for loading state ──────────────────────────────────────────
function LibraryGridSkeleton() {
  return (
    <div
      class="grid grid-cols-4 gap-4 xl:grid-cols-6 2xl:grid-cols-8"
      style={{
        animation: "fadeSlideUp 300ms cubic-bezier(0.22,1,0.36,1) both",
      }}
    >
      <For each={Array.from({ length: 16 })}>
        {() => (
          <div class="aspect-2/3 animate-pulse rounded-xl bg-white/[0.04]" />
        )}
      </For>
    </div>
  );
}

// ── Empty state (no items) ────────────────────────────────────────────────────
function LibraryEmpty(props: { searchTerm?: string }) {
  return (
    <div
      class="col-span-full flex flex-col items-center gap-4 rounded-2xl border border-white/[0.05] bg-white/[0.02] py-20 text-center"
      style={{
        animation: "fadeSlideUp 300ms cubic-bezier(0.22,1,0.36,1) both",
      }}
    >
      <div class="flex h-12 w-12 items-center justify-center rounded-2xl border border-white/[0.07] bg-white/[0.03]">
        <LibraryIcon class="h-6 w-6 text-white/25" />
      </div>
      <div class="space-y-1">
        <Show
          fallback={
            <>
              <p class="font-medium text-sm text-white/45">
                This library is empty
              </p>
              <p class="text-white/22 text-xs">No items have been added yet.</p>
            </>
          }
          when={props.searchTerm}
        >
          <p class="font-medium text-sm text-white/45">No results found</p>
          <p class="text-white/22 text-xs">
            Nothing matched "{props.searchTerm}"
          </p>
        </Show>
      </div>
    </div>
  );
}

// ── Search active banner ──────────────────────────────────────────────────────
function SearchActiveBanner(props: { term: string; count?: number }) {
  return (
    <div
      class="flex items-center justify-between rounded-xl border border-blue-400/15 bg-blue-400/[0.06] px-4 py-2.5"
      style={{
        animation: "fadeSlideUp 250ms cubic-bezier(0.22,1,0.36,1) both",
      }}
    >
      <div class="flex items-center gap-2.5 text-blue-200/90 text-sm">
        <span
          class="h-2 w-2 shrink-0 rounded-full bg-blue-400"
          style={{ animation: "liveDot 1.4s ease-in-out infinite" }}
        />
        <span>
          Searching for{" "}
          <strong class="font-semibold text-blue-100">"{props.term}"</strong>
        </span>
      </div>
      <Show when={props.count !== undefined}>
        <span class="rounded-md bg-blue-400/[0.10] px-2 py-0.5 font-medium text-blue-200/65 text-xs tabular-nums">
          {props.count} result{props.count !== 1 ? "s" : ""}
        </span>
      </Show>
    </div>
  );
}

export default function Page(props: RouteSectionProps) {
  const [{ params }] = splitProps(props, ["params"]);

  const [searchTerm, setSearchTerm] = createSignal("");

  const libraryDetails = JellyfinOperations.getItem(() => params.id);

  const itemsDetails = JellyfinOperations.getItems(() => ({
    parentId: params.id,
    fields: [],
    enableImages: true,
    includeItemTypes: ["Series", "Movie"],
    searchTerm: searchTerm(),
    recursive: true,
  }));

  return (
    <section class="relative flex min-h-screen flex-col">
      {/* Navigation Bar */}
      <QueryBoundary
        loadingFallback={
          <Nav
            breadcrumbs={[
              {
                label: "Libraries",
                icon: <LibraryIcon class="h-4 w-4 shrink-0 opacity-70" />,
              },
            ]}
            class="relative z-50"
            currentPage="Loading..."
            onSearchChange={setSearchTerm}
            searchValue={searchTerm()}
            showSearch={true}
            variant="light"
          />
        }
        query={libraryDetails}
      >
        {(library) => (
          <Nav
            breadcrumbs={[
              {
                label: "Libraries",
                icon: <LibraryIcon class="h-4 w-4 shrink-0 opacity-70" />,
              },
            ]}
            class="relative z-50"
            currentPage={library?.Name || "Library"}
            onSearchChange={setSearchTerm}
            searchValue={searchTerm()}
            showSearch={true}
            variant="light"
          />
        )}
      </QueryBoundary>

      {/* Content Area */}
      <div class="relative z-20 flex-1 px-8 py-8">
        {/* Section heading row */}
        <div class="mb-6 flex items-center justify-between">
          <div class="flex items-baseline gap-3">
            <div
              aria-hidden="true"
              class="h-5 w-0.5 shrink-0 rounded-full bg-blue-400/60"
            />
            <h2 class="font-semibold text-lg text-white/90 tracking-tight">
              <Show fallback="Browse" when={searchTerm()}>
                Results
              </Show>
            </h2>
          </div>

          {/* Item count */}
          <QueryBoundary notFoundFallback={null} query={itemsDetails}>
            {(data) => (
              <Show when={data.length > 0}>
                <span class="rounded-md bg-white/[0.06] px-2 py-0.5 font-medium text-white/28 text-xs tabular-nums">
                  {data.length} item{data.length !== 1 ? "s" : ""}
                </span>
              </Show>
            )}
          </QueryBoundary>
        </div>

        {/* Search active banner */}
        <Show when={searchTerm()}>
          <div class="mb-6">
            <SearchActiveBanner term={searchTerm()} />
          </div>
        </Show>

        {/* Grid */}
        <QueryBoundary
          loadingFallback={
            <div class="space-y-4">
              <div class="flex items-center gap-2 text-sm text-white/35">
                <InlineLoading size="sm" />
                <span>Loading content...</span>
              </div>
              <LibraryGridSkeleton />
            </div>
          }
          notFoundFallback={
            <LibraryEmpty searchTerm={searchTerm() || undefined} />
          }
          query={itemsDetails}
        >
          {(data) => (
            <Show
              fallback={<LibraryEmpty searchTerm={searchTerm() || undefined} />}
              when={data.length > 0}
            >
              <div
                class="grid grid-cols-4 gap-4 xl:grid-cols-6 2xl:grid-cols-8"
                style={{
                  animation:
                    "fadeSlideUp 300ms cubic-bezier(0.22,1,0.36,1) both",
                }}
              >
                <For each={data}>
                  {(item) => <SeriesCard item={item} parentId={params.id} />}
                </For>
              </div>
            </Show>
          )}
        </QueryBoundary>
      </div>
    </section>
  );
}

import {
  ItemFilter,
  type ItemsApiGetItemsRequest,
} from "@jellyfin/sdk/lib/generated-client";
import {
  type RouteSectionProps,
  useNavigate,
  useSearchParams,
} from "@solidjs/router";
import { Effect } from "effect";
import {
  AlertCircle,
  ArrowUp,
  Calendar,
  Check,
  ChevronDown,
  ChevronUp,
  Clock,
  Filter,
  Library as LibraryIcon,
  Play,
  RefreshCw,
  Star,
  Tv,
} from "lucide-solid";
import { create } from "mutative";
import {
  createEffect,
  createSignal,
  For,
  Match,
  onCleanup,
  onMount,
  Show,
  Switch,
  splitProps,
} from "solid-js";
import { ItemActions } from "~/components/ItemActions";
import { EpisodeCard, SeriesCard } from "~/components/media-card";
import { Nav } from "~/components/Nav";
import { QueryBoundary } from "~/components/query-boundary";
import { GlassButton } from "~/components/ui";
import { InlineLoading } from "~/components/ui/loading";
import { useRuntime } from "~/effect/runtime/use-runtime";
import { AuthService } from "~/effect/services/auth";
import {
  JellyfinOperations,
  type JellyfinOperationsType,
} from "~/effect/services/jellyfin/operations";
import { JellyfinService } from "~/effect/services/jellyfin/service";
import {
  createEffectQuery,
  type ExtractQueryData,
} from "~/effect/tanstack/query";

/**
 * Build a compact TV-context label from whichever series / season / episode
 * fields are available on the item, avoiding nested ternaries.
 */
function buildTvContextLabel(item: {
  SeriesName?: string | null;
  SeasonName?: string | null;
  ParentIndexNumber?: number | null;
  IndexNumber?: number | null;
}): string {
  const parts: string[] = [];
  if (item.SeriesName) {
    parts.push(item.SeriesName);
  }
  // Season context: prefer the explicit name, fall back to the numeric index
  if (item.SeasonName) {
    parts.push(item.SeasonName);
  } else if (item.ParentIndexNumber != null) {
    parts.push(`Season ${item.ParentIndexNumber}`);
  }
  // Episode number
  if (item.IndexNumber != null) {
    parts.push(`E${item.IndexNumber}`);
  }
  return parts.join(" · ");
}

const itemPageFilters = ["all", "unplayed", "played", "resumable"] as const;
type ItemPageFilter = (typeof itemPageFilters)[number];

const getItemPageFilter = (filter?: string): ItemPageFilter =>
  itemPageFilters.includes(filter as ItemPageFilter)
    ? (filter as ItemPageFilter)
    : "all";

const getItemFilterSearch = (filter: ItemPageFilter) =>
  filter === "all" ? "" : `?filter=${filter}`;

export default function Page(props: RouteSectionProps) {
  const [{ params }] = splitProps(props, ["params"]);
  const runtime = useRuntime();
  const jf = runtime.runSync(
    Effect.gen(function* () {
      const auth = yield* AuthService;
      const api = yield* auth.getApi();
      return { api };
    })
  );

  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams<{
    filter?: string;
  }>();

  const [isOverviewExpanded, setIsOverviewExpanded] = createSignal(false);
  const [showScrollTop, setShowScrollTop] = createSignal(false);
  const [searchTerm, setSearchTerm] = createSignal("");
  const activeFilter = () => getItemPageFilter(searchParams.filter);
  const setActiveFilter = (filter: ItemPageFilter) => {
    setSearchParams(
      {
        filter: filter === "all" ? undefined : filter,
      },
      { replace: true }
    );
  };
  const itemFilterSearch = () => getItemFilterSearch(activeFilter());

  const parentLibrary = JellyfinOperations.getItem(() => params.id, {
    fields: ["ParentId"],
  });

  const itemDetails = JellyfinOperations.getItem(
    () => params.item_id,
    {
      fields: ["Overview", "Studios", "People"],
    },
    () => ({
      enabled: !!parentLibrary.data?.Id,
    })
  );

  const childrens = createEffectQuery(() => ({
    queryKey: JellyfinOperations.itemsQueryKey({
      parentId: params.item_id,
      searchTerm: `${searchTerm()}::${activeFilter()}`,
    }),
    queryFn: () =>
      Effect.gen(function* () {
        const parentId = params.item_id;
        const client = yield* JellyfinService;

        const filters: (typeof ItemFilter)[keyof typeof ItemFilter][] = [];
        const filter = activeFilter();
        if (filter === "unplayed") {
          filters.push(ItemFilter.IsUnplayed);
        } else if (filter === "played") {
          filters.push(ItemFilter.IsPlayed);
        } else if (filter === "resumable") {
          filters.push(ItemFilter.IsResumable);
        }

        const itemsParams: ItemsApiGetItemsRequest = create(
          {
            parentId,
            fields: ["Overview", "MediaStreams"],
          } as ItemsApiGetItemsRequest,
          (data) => {
            if (searchTerm()) {
              data.searchTerm = searchTerm();
              data.recursive = true;
              data.includeItemTypes = ["Season", "Episode"];
            }

            data.filters = filters.length > 0 ? filters : undefined;
          }
        );

        const items = yield* client.getItems(itemsParams);
        if (!items || items.length === 0) {
          return [];
        }

        items.forEach((item) =>
          JellyfinOperations.itemQueryDataHelpers.setData(
            { id: item.Id as string },
            item
          )
        );

        return items;
      }),
    enabled: !!itemDetails.data?.ChildCount && itemDetails.data.ChildCount > 0,
  }));

  // Scroll to top handler
  let contentAreaRef!: HTMLDivElement;

  const scrollToTop = () => {
    if (contentAreaRef) {
      contentAreaRef.scrollTo({ top: 0, behavior: "smooth" });
    }
  };

  // Show/hide scroll to top button
  onMount(() => {
    const handleScroll = () => {
      if (contentAreaRef) {
        setShowScrollTop(contentAreaRef.scrollTop > 400);
      }
    };

    if (contentAreaRef) {
      contentAreaRef.addEventListener("scroll", handleScroll);
      onCleanup(() =>
        contentAreaRef?.removeEventListener("scroll", handleScroll)
      );
    }
  });

  onMount(() => {
    document.body.style.setProperty("--item-color", "white");
  });

  onCleanup(() => {
    document.body.style.removeProperty("--item-color");
  });

  const getLibraryBackdropUrl = () =>
    `${jf.api.basePath}/Items/${params.id}/Images/Backdrop?quality=10`;

  /**
   * Pick the best backdrop URL from the enriched item data, falling back
   * to the parent library backdrop when the item has none.
   * If the chosen URL fails at runtime, we flip to the library backdrop.
   */
  const [backdropFailed, setBackdropFailed] = createSignal(false);

  // Reset backdrop failure state when navigating to a different item
  createEffect(() => {
    const _id = params.item_id; // track reactively
    setBackdropFailed(false);
  });

  const backdropUrl = () => {
    if (!backdropFailed()) {
      const enriched = itemDetails.data?.Images?.Backdrop;
      if (Array.isArray(enriched) && enriched.length > 0) {
        return enriched[0];
      }
    }
    return getLibraryBackdropUrl();
  };

  const handleBackdropError = (e: Event) => {
    const img = e.currentTarget as HTMLImageElement;
    // Only fallback once to avoid infinite loop when library backdrop also fails
    if (!backdropFailed() && img.src !== getLibraryBackdropUrl()) {
      setBackdropFailed(true);
    }
  };

  return (
    <section class="relative flex min-h-screen flex-col">
      {/* ── Cinematic backdrop ── */}
      <div class="fixed top-0 left-0 h-screen w-full">
        <img
          alt="Backdrop"
          class="h-full w-full object-cover"
          onError={handleBackdropError}
          src={backdropUrl()}
        />
        {/* Multi-layer gradient — deep navy cinematic depth */}
        <div class="absolute inset-0 bg-gradient-to-b from-[#0a0e1a]/60 via-[#0a0e1a]/80 to-[#080c16]" />
        <div class="absolute inset-0 bg-gradient-to-r from-[#0a0e1a]/50 via-transparent to-transparent" />
        <div class="absolute inset-0 backdrop-blur-[2px]" />
      </div>

      {/* ── Error fallback ── */}
      <QueryBoundary
        errorFallback={(err, retry) => (
          <div
            class="relative z-10 flex h-screen w-full flex-col items-center justify-center gap-6"
            style={{
              animation: "fadeSlideUp 350ms cubic-bezier(0.22,1,0.36,1) both",
            }}
          >
            <div class="flex h-14 w-14 items-center justify-center rounded-2xl bg-red-500/10 ring-1 ring-red-500/20 ring-inset">
              <AlertCircle class="h-7 w-7 text-red-400" />
            </div>
            <div class="space-y-1 text-center">
              <p class="font-semibold text-white/80">Failed to load item</p>
              <p class="max-w-xs break-words text-red-400/70 text-sm">
                {err?.message}
              </p>
            </div>
            <button
              class="inline-flex items-center gap-2 rounded-xl border border-white/10 bg-white/[0.07] px-5 py-2.5 text-sm text-white/80 transition-all duration-150 hover:border-blue-400/40 hover:bg-blue-400/[0.08] hover:text-white active:scale-95"
              onClick={retry}
              type="button"
            >
              <RefreshCw class="h-3.5 w-3.5" />
              Retry
            </button>
          </div>
        )}
        loadingFallback={
          <div class="relative z-10 flex h-screen w-full items-center justify-center">
            <InlineLoading message="Loading…" size="lg" />
          </div>
        }
        query={itemDetails}
      >
        {(item) => (
          <div>
            {/* ── Navigation ── */}
            <Nav
              breadcrumbs={[
                {
                  label: (() => {
                    const itemType = item?.Type;
                    if (itemType === "Season" || itemType === "Episode") {
                      return (
                        item?.SeriesName || parentLibrary.data?.Name || "Parent"
                      );
                    }
                    return parentLibrary.data?.Name || "Library";
                  })(),
                  icon: <LibraryIcon class="h-4 w-4 shrink-0 opacity-70" />,
                  onClick: () => {
                    const itemType = item?.Type;

                    if (itemType === "Season" || itemType === "Episode") {
                      const seriesID = item?.SeriesId;
                      if (!seriesID) {
                        return;
                      }
                      // params.id is always the library id in this route
                      navigate(
                        `/library/${params.id}/item/${seriesID}${itemFilterSearch()}`
                      );
                    } else if (itemType === "Movie") {
                      navigate(`/library/${params.id}`);
                    } else {
                      navigate(`/library/${params.id}`);
                    }
                  },
                },
              ]}
              class="relative z-50"
              currentPage={item?.Name || "Loading..."}
              onSearchChange={setSearchTerm}
              searchValue={searchTerm()}
              showSearch={true}
            />

            {/* ── Main content ── */}
            <div
              class="relative z-20 flex-1 overflow-y-auto px-8 py-8 text-white"
              ref={contentAreaRef}
            >
              <div
                class="mx-auto flex h-full max-w-7xl flex-col"
                style={{
                  animation:
                    "fadeSlideUp 400ms cubic-bezier(0.22,1,0.36,1) both",
                }}
              >
                {/* ── Hero Section ── */}
                <div class="space-y-6">
                  {/* Logo or title */}
                  <Show
                    fallback={
                      <h1
                        class="font-bold text-4xl text-white tracking-tight drop-shadow-lg"
                        style={{
                          animation:
                            "fadeSlideUp 350ms 60ms cubic-bezier(0.22,1,0.36,1) both",
                        }}
                      >
                        {item?.Name}
                      </h1>
                    }
                    when={
                      ["Series", "Movie"].includes(item?.Type || "") &&
                      item?.Images?.Logo
                    }
                  >
                    <div
                      class="max-w-sm"
                      style={{
                        animation:
                          "fadeSlideUp 350ms 60ms cubic-bezier(0.22,1,0.36,1) both",
                      }}
                    >
                      <img
                        alt={item?.Name ?? ""}
                        class="h-auto w-full object-contain drop-shadow-2xl"
                        src={item?.Images?.Logo as string}
                      />
                    </div>
                  </Show>

                  {/* ── Metadata chips ── */}
                  <div
                    class="flex flex-wrap items-center gap-2.5"
                    style={{
                      animation:
                        "fadeSlideUp 350ms 100ms cubic-bezier(0.22,1,0.36,1) both",
                    }}
                  >
                    <Show when={item?.CommunityRating}>
                      <div class="flex items-center gap-1.5 rounded-lg bg-blue-400/12 px-2.5 py-1 ring-1 ring-blue-400/25 ring-inset">
                        <Star class="h-3.5 w-3.5 fill-blue-400 text-blue-400" />
                        <span class="font-semibold text-blue-200 text-xs">
                          {item?.CommunityRating?.toFixed(1)}
                        </span>
                      </div>
                    </Show>

                    <Show when={item?.PremiereDate}>
                      <div class="flex items-center gap-1.5 rounded-lg bg-white/[0.06] px-2.5 py-1 ring-1 ring-white/[0.1] ring-inset">
                        <Calendar class="h-3.5 w-3.5 text-white/45" />
                        <span class="font-medium text-white/65 text-xs">
                          {new Date(item?.PremiereDate || "").getFullYear()}
                        </span>
                      </div>
                    </Show>

                    <Show when={!item?.PremiereDate && item?.ProductionYear}>
                      <div class="flex items-center gap-1.5 rounded-lg bg-white/[0.06] px-2.5 py-1 ring-1 ring-white/[0.1] ring-inset">
                        <Calendar class="h-3.5 w-3.5 text-white/45" />
                        <span class="font-medium text-white/65 text-xs">
                          {item?.ProductionYear}
                        </span>
                      </div>
                    </Show>

                    <Show when={item?.RunTimeTicks}>
                      <div class="flex items-center gap-1.5 rounded-lg bg-white/[0.06] px-2.5 py-1 ring-1 ring-white/[0.1] ring-inset">
                        <Clock class="h-3.5 w-3.5 text-white/45" />
                        <span class="font-medium text-white/65 text-xs">
                          {Math.round((item?.RunTimeTicks || 0) / 600_000_000)}{" "}
                          min
                        </span>
                      </div>
                    </Show>

                    <Show when={item?.OfficialRating}>
                      <div class="rounded-lg border border-white/15 bg-white/[0.05] px-2.5 py-1">
                        <span class="font-semibold text-white/55 text-xs tracking-wider">
                          {item?.OfficialRating}
                        </span>
                      </div>
                    </Show>

                    {/* TV context */}
                    <Show
                      when={
                        item?.SeriesName ||
                        item?.SeasonName ||
                        item?.ParentIndexNumber != null ||
                        item?.IndexNumber != null
                      }
                    >
                      <div class="flex items-center gap-1.5 rounded-lg bg-white/[0.06] px-2.5 py-1 ring-1 ring-white/[0.1] ring-inset">
                        <Tv class="h-3.5 w-3.5 text-white/45" />
                        <span class="font-medium text-white/65 text-xs">
                          {buildTvContextLabel(item)}
                        </span>
                      </div>
                    </Show>

                    {/* Watch state */}
                    <Show when={item?.UserData?.Played}>
                      <div class="flex items-center gap-1.5 rounded-lg bg-emerald-400/12 px-2.5 py-1 ring-1 ring-emerald-400/25 ring-inset">
                        <Check class="h-3.5 w-3.5 text-emerald-400" />
                        <span class="font-semibold text-emerald-200 text-xs">
                          Watched
                        </span>
                      </div>
                    </Show>

                    <Show
                      when={
                        !item?.UserData?.Played &&
                        item?.UserData?.PlaybackPositionTicks &&
                        item.UserData.PlaybackPositionTicks > 0
                      }
                    >
                      <div class="flex items-center gap-1.5 rounded-lg bg-amber-400/12 px-2.5 py-1 ring-1 ring-amber-400/25 ring-inset">
                        <Play class="h-3.5 w-3.5 text-amber-400" />
                        <span class="font-semibold text-amber-200 text-xs">
                          {item?.UserData?.PlayedPercentage != null &&
                          item.UserData.PlayedPercentage > 0
                            ? `In Progress · ${Math.round(item.UserData.PlayedPercentage)}%`
                            : "In Progress"}
                        </span>
                      </div>
                    </Show>
                  </div>

                  {/* ── Primary CTA ── */}
                  <div
                    class="flex items-center gap-3 pt-1"
                    style={{
                      animation:
                        "fadeSlideUp 350ms 140ms cubic-bezier(0.22,1,0.36,1) both",
                    }}
                  >
                    <ItemActions
                      item={item}
                      itemId={item.Id || ""}
                      onDone={() => {
                        JellyfinOperations.itemsQueryDataHelpers.invalidateAllQueries();
                      }}
                      variant="detail"
                    />
                  </div>

                  {/* ── Genre pills ── */}
                  <Show when={item?.Genres?.length}>
                    <div
                      class="flex flex-wrap gap-1.5"
                      style={{
                        animation:
                          "fadeSlideUp 350ms 180ms cubic-bezier(0.22,1,0.36,1) both",
                      }}
                    >
                      <For each={item.Genres?.slice(0, 5)}>
                        {(genre) => (
                          <span class="rounded-full border border-white/10 bg-white/[0.06] px-3 py-0.5 font-medium text-white/60 text-xs transition-all duration-150 hover:border-blue-400/30 hover:bg-blue-400/[0.08] hover:text-white/90">
                            {genre}
                          </span>
                        )}
                      </For>
                    </div>
                  </Show>

                  {/* ── Overview ── */}
                  <Show when={item?.Overview}>
                    <div
                      class="max-w-2xl space-y-2 pt-1"
                      style={{
                        animation:
                          "fadeSlideUp 350ms 220ms cubic-bezier(0.22,1,0.36,1) both",
                      }}
                    >
                      <div class="flex items-center justify-between">
                        <h3 class="font-semibold text-blue-300/45 text-xs uppercase tracking-widest">
                          Overview
                        </h3>
                        <button
                          class="flex items-center gap-1 rounded-md px-2 py-0.5 text-white/40 text-xs transition-all duration-150 hover:bg-white/[0.06] hover:text-white/70"
                          onClick={() =>
                            setIsOverviewExpanded(!isOverviewExpanded())
                          }
                          type="button"
                        >
                          <Show
                            fallback={
                              <>
                                <span>More</span>
                                <ChevronDown class="h-3 w-3" />
                              </>
                            }
                            when={isOverviewExpanded()}
                          >
                            <span>Less</span>
                            <ChevronUp class="h-3 w-3" />
                          </Show>
                        </button>
                      </div>
                      <p
                        class={`text-sm text-white/65 leading-relaxed transition-all duration-300 ${
                          isOverviewExpanded() ? "" : "line-clamp-3"
                        }`}
                      >
                        {item?.Overview}
                      </p>
                    </div>
                  </Show>

                  {/* ── Studio + Cast ── */}
                  <Show when={item?.Studios?.length || item?.People?.length}>
                    <div
                      class="grid grid-cols-1 gap-3 pt-2 md:grid-cols-2"
                      style={{
                        animation:
                          "fadeSlideUp 350ms 260ms cubic-bezier(0.22,1,0.36,1) both",
                      }}
                    >
                      <Show when={item?.Studios?.length}>
                        <div class="rounded-xl border border-white/[0.08] bg-white/[0.03] p-5 backdrop-blur-sm">
                          <h4 class="mb-2.5 font-semibold text-blue-300/50 text-xs uppercase tracking-widest">
                            Studio
                          </h4>
                          <p class="font-medium text-sm text-white/80">
                            {item?.Studios?.map((s) => s.Name).join(", ")}
                          </p>
                        </div>
                      </Show>

                      <Show when={item?.People?.slice(0, 4).length}>
                        <div class="rounded-xl border border-white/[0.08] bg-white/[0.03] p-5 backdrop-blur-sm">
                          <h4 class="mb-2.5 font-semibold text-blue-300/50 text-xs uppercase tracking-widest">
                            Cast
                          </h4>
                          <div class="space-y-1.5">
                            <For each={item.People?.slice(0, 4)}>
                              {(person) => (
                                <div class="flex items-baseline gap-2 text-sm">
                                  <span class="truncate font-medium text-white/80">
                                    {person.Name}
                                  </span>
                                  <Show when={person.Role}>
                                    <span class="truncate text-white/35 text-xs">
                                      {person.Role}
                                    </span>
                                  </Show>
                                </div>
                              )}
                            </For>
                          </div>
                        </div>
                      </Show>
                    </div>
                  </Show>
                </div>

                {/* ── Children / Content Section ── */}
                <div
                  class="mt-14 flex-1 border-blue-400/[0.08] border-t pt-8"
                  style={{
                    animation:
                      "fadeSlideUp 400ms 300ms cubic-bezier(0.22,1,0.36,1) both",
                  }}
                >
                  <QueryBoundary
                    errorFallback={(err, retry) => (
                      <div class="flex flex-col items-center gap-4 rounded-xl border border-red-500/[0.15] bg-red-500/[0.04] px-6 py-10 text-center">
                        <div class="flex h-10 w-10 items-center justify-center rounded-2xl bg-red-500/[0.12] ring-1 ring-red-500/[0.2] ring-inset">
                          <AlertCircle class="h-5 w-5 text-red-400" />
                        </div>
                        <div class="space-y-1">
                          <p class="font-medium text-sm text-white/70">
                            Failed to load content
                          </p>
                          <p class="text-red-400/70 text-xs">{err?.message}</p>
                        </div>
                        <button
                          class="inline-flex items-center gap-1.5 rounded-lg border border-white/[0.1] bg-white/[0.07] px-4 py-2 text-sm text-white/80 transition-all duration-150 hover:border-blue-400/40 hover:bg-blue-400/[0.08] hover:text-white active:scale-95"
                          onClick={retry}
                          type="button"
                        >
                          <RefreshCw class="h-3.5 w-3.5" />
                          Retry
                        </button>
                      </div>
                    )}
                    loadingFallback={
                      <div class="flex items-center justify-center py-16">
                        <InlineLoading message="Loading content…" size="md" />
                      </div>
                    }
                    notFoundFallback={
                      <ItemsRender
                        activeFilter={activeFilter()}
                        items={[]}
                        onFilterChange={setActiveFilter}
                        parentId={params.id}
                        parentItem={item}
                      />
                    }
                    notStartedFallback={
                      <ItemsRender
                        activeFilter={activeFilter()}
                        items={[]}
                        onFilterChange={setActiveFilter}
                        parentId={params.id}
                        parentItem={item}
                      />
                    }
                    query={childrens}
                  >
                    {(items) => (
                      <ItemsRender
                        activeFilter={activeFilter()}
                        items={items}
                        onFilterChange={setActiveFilter}
                        parentId={params.id}
                        parentItem={item}
                      />
                    )}
                  </QueryBoundary>
                </div>
              </div>
            </div>
          </div>
        )}
      </QueryBoundary>

      {/* ── Scroll to top ── */}
      <Show when={showScrollTop()}>
        <GlassButton
          class="fade-in slide-in-from-bottom-4 fixed right-8 bottom-8 z-50 animate-in text-white shadow-xl"
          onClick={scrollToTop}
          size="icon-lg"
        >
          <ArrowUp class="h-5 w-5" />
        </GlassButton>
      </Show>
    </section>
  );
}

interface ItemsRenderProsp {
  parentItem: ExtractQueryData<ReturnType<JellyfinOperationsType["getItem"]>>;
  items:
    | ExtractQueryData<ReturnType<JellyfinOperationsType["getItems"]>>
    | undefined;
  parentId: string;
  activeFilter: ItemPageFilter;
  onFilterChange: (filter: ItemPageFilter) => void;
}

const FilterButton = (props: {
  filter: ItemsRenderProsp["activeFilter"];
  label: string;
  activeFilter: ItemsRenderProsp["activeFilter"];
  onFilterChange: ItemsRenderProsp["onFilterChange"];
}) => (
  <button
    class={`rounded-full px-3 py-1 font-medium text-xs transition-all duration-150 ${
      props.activeFilter === props.filter
        ? "border border-blue-400/40 bg-blue-400/15 text-blue-200 shadow-[0_0_12px_rgba(96,165,250,0.15)]"
        : "border border-white/[0.08] bg-white/[0.05] text-white/50 hover:border-white/20 hover:bg-white/10 hover:text-white/80"
    }`}
    onClick={() => props.onFilterChange(props.filter)}
    type="button"
  >
    {props.label}
  </button>
);

function ItemsRender(props: ItemsRenderProsp) {
  const [{ parentItem, items, parentId, activeFilter, onFilterChange }] =
    splitProps(props, [
      "parentItem",
      "items",
      "parentId",
      "activeFilter",
      "onFilterChange",
    ]);

  return (
    <Switch
      fallback={
        <div class="flex flex-col items-center gap-3 py-16 text-center">
          <p class="font-medium text-sm text-white/40">Nothing to show here</p>
        </div>
      }
    >
      <Match when={!parentItem}>
        <div class="flex flex-col items-center gap-3 py-16 text-center">
          <p class="font-medium text-sm text-white/40">Item not found</p>
        </div>
      </Match>
      <Match when={!parentItem?.Type}>
        <div class="flex flex-col items-center gap-3 py-16 text-center">
          <p class="font-medium text-sm text-white/40">No content available</p>
        </div>
      </Match>

      <Match when={parentItem?.Type === "Series"}>
        <div class="space-y-6">
          {/* Section header */}
          <div class="flex items-center justify-between gap-4">
            <div class="flex items-baseline gap-2">
              <h2 class="font-semibold text-lg text-white/90">Seasons</h2>
              <span class="font-medium text-white/35 text-xs">
                {items?.length} {items?.length === 1 ? "Season" : "Seasons"}
              </span>
            </div>

            <div class="flex items-center gap-1.5">
              <Filter class="h-3.5 w-3.5 text-white/30" />
              <FilterButton
                activeFilter={activeFilter}
                filter="all"
                label="All"
                onFilterChange={onFilterChange}
              />
              <FilterButton
                activeFilter={activeFilter}
                filter="unplayed"
                label="Unwatched"
                onFilterChange={onFilterChange}
              />
              <FilterButton
                activeFilter={activeFilter}
                filter="played"
                label="Watched"
                onFilterChange={onFilterChange}
              />
              <FilterButton
                activeFilter={activeFilter}
                filter="resumable"
                label="In Progress"
                onFilterChange={onFilterChange}
              />
            </div>
          </div>

          {/* Empty state */}
          <Show when={!items?.length}>
            <div class="flex flex-col items-center gap-3 rounded-xl border border-white/[0.06] bg-white/[0.03] py-16 text-center">
              <p class="font-medium text-sm text-white/40">No seasons found</p>
              <p class="text-white/25 text-xs">Try changing the filter above</p>
            </div>
          </Show>

          <div class="grid grid-cols-3 gap-6 lg:grid-cols-4 xl:grid-cols-5 2xl:grid-cols-6">
            <For each={items}>
              {(item) => (
                <SeriesCard
                  item={item}
                  parentId={parentId}
                  search={getItemFilterSearch(activeFilter)}
                />
              )}
            </For>
          </div>
        </div>
      </Match>

      <Match when={parentItem?.Type === "Movie"}>
        <div class="space-y-5">
          <h2 class="font-semibold text-lg text-white/90">Watch Movie</h2>
          <EpisodeCard item={parentItem} />
        </div>
      </Match>

      <Match when={parentItem?.Type === "Season"}>
        <div class="space-y-6">
          {/* Section header */}
          <div class="flex items-center justify-between gap-4">
            <div class="flex items-baseline gap-2">
              <h2 class="font-semibold text-lg text-white/90">Episodes</h2>
              <span class="font-medium text-white/35 text-xs">
                {items?.length} {items?.length === 1 ? "Episode" : "Episodes"}
              </span>
            </div>

            <div class="flex items-center gap-1.5">
              <Filter class="h-3.5 w-3.5 text-white/30" />
              <FilterButton
                activeFilter={activeFilter}
                filter="all"
                label="All"
                onFilterChange={onFilterChange}
              />
              <FilterButton
                activeFilter={activeFilter}
                filter="unplayed"
                label="Unwatched"
                onFilterChange={onFilterChange}
              />
              <FilterButton
                activeFilter={activeFilter}
                filter="played"
                label="Watched"
                onFilterChange={onFilterChange}
              />
              <FilterButton
                activeFilter={activeFilter}
                filter="resumable"
                label="In Progress"
                onFilterChange={onFilterChange}
              />
            </div>
          </div>

          {/* Empty state */}
          <Show when={!items?.length}>
            <div class="flex flex-col items-center gap-3 rounded-xl border border-white/[0.06] bg-white/[0.03] py-16 text-center">
              <p class="font-medium text-sm text-white/40">No episodes found</p>
              <p class="text-white/25 text-xs">Try changing the filter above</p>
            </div>
          </Show>

          <div class="space-y-4">
            <For each={items}>{(item) => <EpisodeCard item={item} />}</For>
          </div>
        </div>
      </Match>
    </Switch>
  );
}

export type MediaItemType =
  | "movie"
  | "series"
  | "season"
  | "episode"
  | "library"
  | "unknown";

export type Artwork = {
  primary?: string;
  backdrop?: string;
  logo?: string;
};

export type TrackSummary = {
  audioLanguages: string[];
  subtitleLanguages: string[];
};

export type MediaPerson = {
  name: string;
  role?: string;
  type?: string;
  imageUrl?: string;
};

export type MediaItem = {
  id: string;
  name: string;
  type: MediaItemType;
  jellyfinType?: string;
  overview?: string;
  year?: number;
  premiereDate?: string;
  runtimeTicks?: number;
  communityRating?: number;
  officialRating?: string;
  genres: string[];
  parentId?: string;
  seriesId?: string;
  seriesName?: string;
  seasonName?: string;
  indexNumber?: number;
  childCount?: number;
  locationType?: string;
  studios: string[];
  people: MediaPerson[];
  trackSummary: TrackSummary;
  userData: {
    played: boolean;
    favorite: boolean;
    playbackPositionTicks?: number;
    playedPercentage?: number;
    unplayedItemCount?: number;
  };
  artwork: Artwork;
};

export type Library = {
  id: string;
  name: string;
  collectionType?: string;
  itemCount?: number;
  artwork: Artwork;
};

export type PlaybackChapter = {
  name?: string;
  startPositionTicks?: number;
};

export type PlaybackSource = {
  id?: string;
  path?: string;
