function buildTvContextLabel(item: MediaItem): string {
  const parts: string[] = [];
  if (item.seriesName) parts.push(item.seriesName);
  if (item.seasonName) parts.push(item.seasonName);
  if (item.indexNumber != null) parts.push(`E${item.indexNumber}`);
  return parts.join(" · ");
}

